public enum CliVerb
{
    Help,
    List,
    Apply,
    Enable,
    Disable,
    Import,
    Merge,
}

/// <summary>A parsed command: a <see cref="CliVerb"/> plus its single argument (a preset name or file path), if any.</summary>
public sealed record CliCommand(CliVerb Verb, string? Argument);

